import {money,cents,today,uid,categoryList,cycleBounds,summary,validateBackup,validateTx,fundingAccount} from './domain.mjs';
import {upgrade,addDays,addMonths,planRows,planRemaining,createPlan,editPlan,payPlan,refundPlan,saveBill,upcoming,confirmBill,forecast,balanceAt,duplicates,reconcile,restoreTransaction,calendarICS,budgetStatus,reversePlanPayment,reversePlanRefund} from './advanced-core.mjs';
import * as backups from './backup.mjs';
export function createAdvancedUI(c){
const {E,I,toast,openSheet,download}=c,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],state=()=>c.getState(),book=()=>c.getBook(),f=()=>state().features,scope=()=>book()==='all'?null:book(),bookId=()=>scope()||'personal';
let historyRows=[],cloudRows=[],historyError='',externalStatus='',folderLabel='',password='',prepared=false,dirty=false,backupTimer,historyQueue=Promise.resolve(),externalTask=null,busy=false,lastExternal=0;
let config={auto:false,target:'folder',clientId:'',lastBackup:null,notifications:false};try{config={...config,...JSON.parse(localStorage.getItem('yoyu-backup-config')||'{}')}}catch{}
const configKey=()=>backups.getBackupScope()==='yoyu-ledger-data-v1'?'yoyu-backup-config':'yoyu-backup-config:'+backups.getBackupScope();
function saveConfig(){localStorage.setItem(configKey(),JSON.stringify(config))}
async function switchScope(scope){clearTimeout(backupTimer);password='';prepared=false;dirty=false;folderLabel='';externalStatus='';historyError='';historyRows=[];cloudRows=[];backups.setBackupScope(scope);config={auto:false,target:'folder',clientId:'',lastBackup:null,notifications:false};try{config={...config,...JSON.parse(localStorage.getItem(configKey())||'{}')}}catch{};await historyQueue;}
const set=(next,msg)=>{if(c.commit(next)){c.render();if(msg)toast(msg);return true}return false};
const acc=id=>state().accounts.find(a=>a.id===id)?.name||'未指定',bookName=id=>f().books.find(b=>b.id===id)?.name||'生活';
const input=(label,id,value='',type='text',extra='')=>`<label class="field">${label}<input id="${id}" type="${type}" value="${E(value)}" ${extra}></label>`;
const select=(label,id,options,value)=>`<label class="field">${label}<select id="${id}">${options.map(([v,l])=>`<option value="${E(v)}" ${v===value?'selected':''}>${E(l)}</option>`).join('')}</select></label>`;
const accounts=(value,filter=()=>true)=>state().accounts.filter(a=>a.kind!=='receivable').filter(filter).map(a=>[a.id,a.name]);
const categories=()=>categoryList(state()).map(v=>[v,v]);
const books=()=>f().books.map(b=>[b.id,b.name]);
const formError=err=>{const el=$('#advanced-error');if(el)el.textContent=err.message||String(err);else toast(err.message||String(err))};
const submit=(id,fn)=>{$(id).onsubmit=async e=>{e.preventDefault();try{await fn()}catch(err){formError(err)}}};
function sheet(title,body){openSheet(title,body)}
function finish(next,msg){if(set(next,msg))$('#sheet').close()}
const errorBox='<div class="inline-error" id="advanced-error" role="alert"></div>';
const number=(id)=>cents($(id).value);
const title=(h,p,actions='')=>`<div class="page-title"><div><div class="eyebrow">MORE ROOM FOR YOUR EVERYDAY</div><h1>${h}</h1><p class="subtitle">${p}</p></div><div class="controls">${actions}</div></div>`;
const empty=text=>`<div class="empty">${I('leaf')}<br>${text}</div>`;
function toolbar(){return `<div class="workspace-strip"><label>帳本 <select id="active-book" aria-label="切換帳本"><option value="all" ${book()==='all'?'selected':''}>全部帳本</option>${books().map(([v,l])=>`<option value="${E(v)}" ${v===book()?'selected':''}>${E(l)}</option>`).join('')}</select></label><label>月份 <input type="month" id="advanced-month" aria-label="工作區月份" value="${E(c.getMonth())}"></label><button class="text-btn" data-advanced-page="budgets">管理帳本與預算 ${I('right')}</button><span class="period-hint">起算日：每月${f().cycleDay}日</span></div><div class="tools-nav" aria-label="進階工具">${[['invoices','發票紀錄'],['settlements','代墊／分帳'],['available','可花金額'],['bills','待繳／固定收支'],['plans','分期管理'],['cashflow','30天現金流'],['reconcile','帳戶對帳'],['budgets','預算／帳本']].map(([id,l])=>`<button data-advanced-page="${id}">${l}</button>`).join('')}</div>`}
function dueRow(e){return `<div class="due-row"><div><strong>${E(e.name)}</strong><small>${E(e.due)} · ${E(bookName(e.bookId))} · ${E(acc(e.account))}${e.toAccount?' → '+E(acc(e.toAccount)):''}</small></div><div class="due-amount sensitive ${e.type==='income'?'positive':''}">${e.type==='income'?'+':''}${money(e.amount)}</div><button class="secondary" data-confirm-due="${E(e.id)}">${e.type==='income'?'確認入帳':'記錄付款'}</button></div>`}
function homePanel(){const all=upcoming(state(),{from:addMonths(today(),-12),to:addDays(today(),30),bookId:scope()}),out=all.filter(e=>e.type!=='income'),soon=out.filter(e=>e.due<=addDays(today(),7)),overdue=out.filter(e=>e.due<today()),flow=forecast(state());const limits=(scope()?budgetStatus(state(),c.getMonth(),bookId()):f().books.flatMap(b=>budgetStatus(state(),c.getMonth(),b.id))).filter(x=>x.used>x.limit);return `<div class="daily-focus"><div class="focus-heading"><span class="eyebrow">TODAY AT A GLANCE</span><h2>今天，先看這三件事。</h2></div><div class="focus-grid"><button data-advanced-page="bills"><span>七天內待繳</span><strong class="sensitive">${money(soon.reduce((n,e)=>n+e.amount,0))}</strong><small>${soon.length}筆待確認${overdue.length?' · '+overdue.length+'筆逾期未確認':''}</small></button><button data-advanced-page="cashflow"><span>目前現金／銀行</span><strong class="sensitive">${money(flow.initial)}</strong><small>所有帳本共用 · 不含信用額度</small></button><button data-advanced-page="budgets"><span>需要留意</span><strong>${limits.length?limits.length+'項超出預算':out.length?out.length+'筆未來帳款':'開始記下日常'}</strong><small>${flow.minimum<0?'依已知排程，現金流可能低於0':'尚未確認付款不會自動扣帳'}</small></button></div>${soon.length?`<div class="focus-due">${soon.slice(0,3).map(dueRow).join('')}<button class="text-btn" data-advanced-page="bills">查看全部待繳 ${I('right')}</button></div>`:''}</div>`}
function plansPage(){const plans=f().plans.filter(p=>!scope()||p.bookId===scope());return title('把分期，看得清楚。','消費只記一次。未來排程與實際還款，分開管理。',`<button class="primary" id="new-plan">${I('plus')}建立分期</button>`)+`<div class="notice" style="margin-bottom:20px">建立時只認列商品本金；排程中的預計手續費不先入帳。每次確認還款時可修改實繳本金、費用與付款日。已記過的消費可直接連結，避免重複。</div><div class="plan-grid">${plans.length?plans.map(p=>{const rows=planRows(p),remaining=planRemaining(p),next=rows.find(r=>r.remaining);return `<article class="card"><div class="card-heading"><h2>${E(p.name)}</h2><button class="text-btn" data-edit-plan="${E(p.id)}">修改 ${I('edit')}</button></div><small class="metric-note">${E(acc(p.account))} · ${E(bookName(p.bookId))} · ${p.count}期</small><div class="metric-value sensitive">${money(remaining)}</div><p class="help">待還本金 · 原始本金 ${money(p.totalPrincipal)}${next?' · 下一期 '+next.due:' · 本金已結清'}</p><div class="row" style="flex-wrap:wrap"><button class="secondary" data-plan-detail="${E(p.id)}">期數與紀錄</button><button class="secondary" data-plan-payoff="${E(p.id)}" ${remaining?'':'disabled'}>提前結清</button><button class="text-btn" data-plan-refund="${E(p.id)}">記錄退款</button></div></article>`}).join(''):empty('建立第一個分期，或把已有的消費加入管理。')}</div>`}
function planForm(id=null){const p=f().plans.find(p=>p.id===id),debt=accounts('',a=>['card','bnpl'].includes(a.kind));if(!debt.length){toast('請先新增信用卡或先買後付帳戶');c.navigate('accounts');return}const debtId=p?.account||debt[0][0];const expenseOptions=state().transactions.filter(t=>t.type==='expense'&&!t.origin&&state().accounts.some(a=>a.id===fundingAccount(state(),t.account)&&['card','bnpl'].includes(a.kind))).map(t=>[t.id,t.date+' · '+t.note+' · '+money(t.amount)+' · '+acc(t.account)]);sheet(p?'修改分期方案':'建立分期方案',`<form id="plan-form">${input('方案名稱','plan-name',p?.name||'','text','required maxlength="200"')}${p?'':select('消費入帳方式','plan-existing',[['','建立新的消費紀錄'],...expenseOptions],'')}${p?'':select('分期帳戶','plan-account',debt,debtId)}${p?'':`<div class="row">${input('商品本金（NT$）','plan-principal','','number','required min="0.01" step="0.01"')}${input('消費日期','plan-date',today(),'date','required')}</div>${select('消費分類','plan-category',categories(),'購物')}${select('所屬帳本','plan-book',books(),bookId())}`}<div class="row">${input('期數','plan-count',p?.count||3,'number','required min="1" max="120"')}${input('首期繳款日','plan-due',p?.firstDue||addMonths(today(),1),'date','required')}</div>${input('預計總手續費／利息（NT$）','plan-fee',(p?.totalFee||0)/100,'number','required min="0" step="0.01"')}${select('預設實際付款帳戶','plan-source',accounts('',a=>fundingAccount(state(),a.id)!==debtId),p?.source||state().accounts.find(a=>a.kind==='bank')?.id||state().accounts[0].id)}<p class="help">金額以業者帳單為準，不自動推定費率。預計費用只用於排程估算，確認付款時才認列實際費用。已有還款時，保留原期數。</p>${errorBox}<button class="primary full">${p?'儲存修改':'建立並確認消費'}</button></form>`);$('#plan-existing')?.addEventListener('change',e=>{const t=state().transactions.find(t=>t.id===e.target.value);if(t){$('#plan-name').value=t.note;$('#plan-principal').value=t.amount/100;$('#plan-date').value=t.date;$('#plan-account').value=fundingAccount(state(),t.account);$('#plan-category').value=t.category;$('#plan-book').value=t.bookId||'personal'}});submit('#plan-form',()=>{const input={name:$('#plan-name').value,count:Number($('#plan-count').value),firstDue:$('#plan-due').value,totalFee:number('#plan-fee'),source:$('#plan-source').value};const next=p?editPlan(state(),p.id,input):createPlan(state(),{...input,totalPrincipal:number('#plan-principal'),purchaseDate:$('#plan-date').value,account:$('#plan-account').value,category:$('#plan-category').value,bookId:$('#plan-book').value,existingTxId:$('#plan-existing').value||null});finish(next,p?'分期方案已更新':'分期方案已建立')})}
function planDetail(id){const p=f().plans.find(p=>p.id===id);sheet(p.name+' · 分期明細',`<p class="help">${E(acc(p.account))} · 本金 ${money(p.totalPrincipal)} · 已退款 ${money(p.refunds.reduce((n,r)=>n+r.amount,0))}</p><div class="schedule-list">${planRows(p).map(r=>`<div class="schedule-row"><div><strong>第${r.index+1}期 · ${r.due}</strong><small>原本金 ${money(r.originalPrincipal)} · 已還 ${money(r.paidPrincipal)}${r.canceled?' · 退款抵減 '+money(r.canceled):''}<br>預計費用 ${money(r.fee)} · 已認列費用 ${money(r.paidFee)}</small></div><div><strong class="sensitive">${money(r.remaining)}</strong><small>待還本金</small>${r.remaining?`<button class="text-btn" data-pay-installment="${r.index}">記錄實繳 →</button>`:'<small class="positive">本金已處理</small>'}</div></div>`).join('')}</div><h3 style="font-size:14px;margin-top:24px">實際還款紀錄</h3>${p.payments.map(v=>`<p class="help">${v.date} · ${E(acc(v.source))} · 本金 ${money(v.allocations.reduce((n,a)=>n+a.principal,0))} ＋ 費用 ${money(v.allocations.reduce((n,a)=>n+a.fee,0))} <button class="text-btn" data-reverse-payment="${E(v.id)}">撤銷記帳</button></p>`).join('')||'<p class="help">還沒有實繳紀錄。</p>'}${p.refunds.length?'<h3 style="font-size:14px">退款紀錄</h3>'+p.refunds.map(r=>`<p class="help">${r.date} · ${money(r.amount)} <button class="text-btn" data-reverse-refund="${E(r.id)}">撤銷記帳</button></p>`).join(''):''}<p class="help">退款可能改變業者費用，請在「修改」依新帳單調整預計費用。已繳超過退款後應付金額時，帳戶將呈現溢繳款。</p>`);$$('[data-pay-installment]').forEach(b=>b.onclick=()=>paymentForm(id,Number(b.dataset.payInstallment)));$$('[data-reverse-payment]').forEach(b=>b.onclick=()=>{if(confirm('撤銷這次還款記帳？會一併移除對應轉帳與費用，恢復待還進度；不會取消業者實際付款。'))finish(reversePlanPayment(state(),id,b.dataset.reversePayment),'還款記帳已撤銷')});$$('[data-reverse-refund]').forEach(b=>b.onclick=()=>{if(confirm('撤銷這次退款記帳？不會取消業者實際退款。'))finish(reversePlanRefund(state(),id,b.dataset.reverseRefund),'退款記帳已撤銷')})}
function paymentForm(id,index=null){const p=f().plans.find(p=>p.id===id),r=index===null?null:planRows(p).find(r=>r.index===index);sheet(index===null?'提前／合併結清':'記錄第'+(index+1)+'期實繳',`<form id="payment-form"><p class="help">${E(p.name)} · ${E(acc(p.account))}</p><div class="row">${input('本次實繳本金（NT$）','pay-principal',(r?.remaining??planRemaining(p))/100,'number','required min="0.01" step="0.01"')}${input('本次實際費用（NT$）','pay-fee',(r?.remainingFee||0)/100,'number','required min="0" step="0.01"')}</div>${select('實際付款帳戶','pay-source',accounts('',a=>fundingAccount(state(),a.id)!==p.account),p.source)}${input('實際付款日期','pay-date',today(),'date','required')}<div class="notice">會新增一筆還款轉帳；若有費用，另外新增費用支出。本金不重複算消費。提前結清時，請填業者實收費用。</div>${errorBox}<button class="primary full" style="margin-top:16px">確認付款並入帳</button></form>`);submit('#payment-form',()=>finish(payPlan(state(),id,{index,principal:number('#pay-principal'),fee:number('#pay-fee'),source:$('#pay-source').value,date:$('#pay-date').value}),'實繳紀錄已儲存'))}
function refundForm(id){sheet('記錄商品本金退款',`<form id="refund-plan-form">${input('實際退款本金（NT$）','refund-amount','','number','required min="0.01" step="0.01"')}${input('退款入帳日','refund-date',today(),'date','required')}<p class="help">退款回補分期帳戶，並優先減少後面尚未繳的本金。費用退還請另外記「退款／手續費與利息」，再核對業者帳單。</p>${errorBox}<button class="primary full">確認退款入帳</button></form>`);submit('#refund-plan-form',()=>finish(refundPlan(state(),id,{amount:number('#refund-amount'),date:$('#refund-date').value}),'退款已記錄'))}
function billsPage(){const pending=upcoming(state(),{from:addMonths(today(),-12),to:addMonths(today(),3),bookId:scope()}),bills=f().bills.filter(b=>!scope()||b.bookId===scope());return title('接下來要繳什麼？','過去一年未確認與未來三個月的排程，一起看清楚。',`<button class="secondary" id="calendar-export">${I('download')}手機日曆提醒</button><button class="primary" id="new-bill">${I('plus')}固定收支</button>`)+`<div class="card" style="margin-bottom:24px"><div class="card-heading"><h2>待確認收支</h2><small>確認前不會自動入帳</small></div>${pending.length?pending.map(dueRow).join(''):empty('目前沒有待確認的排程。')}</div><div class="card"><div class="card-heading"><h2>固定支出、收入與訂閱</h2></div>${bills.length?bills.map(b=>`<div class="due-row"><div><strong>${E(b.name)} ${b.active?'':'（已暫停）'}</strong><small>${{monthly:'每月',weekly:'每週',yearly:'每年'}[b.interval]} · ${E(bookName(b.bookId))} · ${E(acc(b.account))}</small></div><span class="sensitive">${money(b.amount)}</span><button class="text-btn" data-edit-bill="${E(b.id)}">編輯</button><button class="text-btn" data-toggle-bill="${E(b.id)}">${b.active?'暫停':'恢復'}</button></div>`).join(''):empty('把房租、訂閱或固定收入加進來，每期確認就好。')}</div><div class="notice" style="margin-top:20px">避免為同一分期再建立固定還款排程，以免預估重複。手機日曆提醒需匯入後確認通知設定；帳單變動後請更新匯入，網頁不會在關閉後自行執行。</div>`}
function billForm(id=null){const b=f().bills.find(b=>b.id===id);sheet(b?'編輯固定收支':'新增固定收支／訂閱',`<form id="bill-form">${input('項目名稱','bill-name',b?.name||'','text','required maxlength="200"')}<div class="row">${select('類型','bill-type',[['expense','支出'],['income','收入'],['transfer','轉帳／繳款']],b?.type||'expense')}${input('每次預計金額（NT$）','bill-amount',(b?.amount||0)/100,'number','required min="0.01" step="0.01"')}</div><div class="row">${select('使用／轉出帳戶','bill-account',accounts(),b?.account||state().accounts[0].id)}${select('轉入帳戶（轉帳用）','bill-to',accounts(),b?.toAccount||state().accounts[1]?.id)}</div><div class="row">${select('分類','bill-category',categories(),b?.category||'生活')}${select('所屬帳本','bill-book',books(),b?.bookId||bookId())}</div><div class="row">${input('首期日期','bill-start',b?.start||today(),'date','required')}${select('週期','bill-interval',[['monthly','每月'],['weekly','每週'],['yearly','每年']],b?.interval||'monthly')}</div>${input('結束日期（可留空）','bill-end',b?.end||'','date')}<p class="help">每月31日會在沒有31日的月份使用月底，下一個月仍回到31日。每期只產生待確認項目，不會直接扣款。</p>${errorBox}<button class="primary full">儲存固定收支</button></form>`);submit('#bill-form',()=>finish(saveBill(state(),{name:$('#bill-name').value.trim(),type:$('#bill-type').value,amount:number('#bill-amount'),account:$('#bill-account').value,toAccount:$('#bill-to').value,category:$('#bill-category').value,bookId:$('#bill-book').value,start:$('#bill-start').value,end:$('#bill-end').value||null,interval:$('#bill-interval').value,active:b?.active??true},id),'固定收支已儲存'))}
function confirmDue(id){const e=upcoming(state(),{from:addMonths(today(),-12),to:addMonths(today(),3)}).find(e=>e.id===id);if(!e){toast('這筆可能已確認，請重新整理');return}if(e.kind==='plan'){paymentForm(e.ref,e.index);return}sheet('確認本次實際收支',`<form id="confirm-bill-form"><p class="help">${E(e.name)} · 原排程 ${e.due}</p>${input('實際金額（NT$）','confirm-amount',e.amount/100,'number','required min="0.01" step="0.01"')}${input('實際入帳日','confirm-date',today(),'date','required')}${errorBox}<button class="primary full">確認並入帳</button></form>`);submit('#confirm-bill-form',()=>finish(confirmBill(state(),e.ref,e.due,{amount:number('#confirm-amount'),date:$('#confirm-date').value}),'本期已確認入帳'))}
function cashflowPage(){const flow=forecast(state()),chart=flow.daily.filter((_,i)=>i%5===0||i===30),scale=Math.max(1,...chart.map(x=>Math.abs(x.balance)));return title('未來30天，心裡有底。','依所有帳本的已知排程預估；不包含尚未建立的消費與收入。')+`<div class="stat-grid">${[['目前現金／銀行',flow.initial],['30天後預估',flow.end],['期間最低預估',flow.minimum]].map(([l,n])=>`<div class="card"><div class="card-label">${l}</div><div class="metric-value sensitive ${n<0?'overspent':''}">${money(n)}</div></div>`).join('')}</div><div class="card"><div class="card-heading"><h2>現金流趨勢</h2><small>所有帳本共用的現金帳戶</small></div><div class="chart-wrap">${chart.map(x=>`<div class="bar-col"><span class="bar-value sensitive ${x.balance<0?'overspent':''}">${money(x.balance)}</span><div class="bar" style="height:${Math.max(2,Math.abs(x.balance)/scale*155)}px;${x.balance<0?'background:var(--danger)':''}"></div><span class="bar-label">${x.date.slice(5)}</span></div>`).join('')}</div></div><div class="card" style="margin-top:24px"><div class="card-heading"><h2>預估變動明細</h2></div>${flow.events.length?flow.events.map(e=>`<div class="due-row"><div><strong>${E(e.name)}</strong><small>${e.date}${e.due&&e.due<today()?' · 過期未確認，暫列今天':''} · ${e.estimated?'尚未確認':'已記錄的未來交易'}</small></div><strong class="sensitive ${e.delta>=0?'positive':''}">${e.delta>0?'+':''}${money(e.delta)}</strong></div>`).join(''):empty('還沒有會影響現金流的已知排程。')}</div><p class="help">信用卡與先買後付額度不算現金。其消費不直接減少現金，還款排程才減少；轉帳在兩個現金帳戶間移動則淨變動為0。尚未設定繳款排程的信用卡／先買後付待還款，不會自動列入預估。逾期未確認只表示帳本尚未確認，不代表業者判定逾期。</p>`}
function reconcilePage(){const dup=duplicates(state());return title('讓帳本，對得上現實。','先記錄差異、找出原因，需要時再由你確認調整。',`<button class="primary" id="new-reconcile">${I('check')}開始對帳</button>`)+`<div class="card"><div class="card-heading"><h2>疑似重複紀錄</h2><small>${dup.length}組 · 不會自動刪除</small></div>${dup.length?dup.slice(0,30).map(g=>`<div class="due-row"><div><strong>${E(g[0].note)} · ${g.length}筆</strong><small>${g[0].date} · ${E(acc(g[0].account))}</small></div><strong class="sensitive">${money(g[0].amount)}</strong><button class="text-btn" data-inspect-tx="${E(g[0].id)}">檢查紀錄 →</button></div>`).join(''):empty('目前沒有完全相同的日期、金額、項目與來源帳戶。')}</div><div class="card" style="margin-top:24px"><div class="card-heading"><h2>對帳歷史</h2></div>${f().reconciliations.length?f().reconciliations.slice(0,30).map(r=>`<div class="due-row"><div><strong>${E(acc(r.account))} · ${r.date}</strong><small>帳面 ${money(r.expected)}／實際 ${money(r.actual)} · ${r.txId?'已由你確認新增調整':'僅記錄差異，未改餘額'}</small></div><strong class="sensitive ${r.difference?'overspent':'positive'}">${money(r.difference)}</strong></div>`).join(''):empty('完成第一次對帳後，紀錄會留在這裡。')}</div>`}
function reconcileForm(){sheet('核對帳戶餘額',`<form id="reconcile-form">${select('帳戶','reconcile-account',accounts('',a=>!(a.kind==='mobile'&&a.paymentMode==='linked')),state().accounts[0].id)}${input('對帳日期','reconcile-date',today(),'date','required')}${input('當天實際餘額（NT$）','reconcile-actual','','number','required step="0.01"')}<p class="help" id="expected-balance"></p>${input('備註','reconcile-note','','text','maxlength="200"')}<label class="check"><input type="checkbox" id="reconcile-adjust"><span>我已確認差異，新增一筆「對帳調整」收支，讓帳本餘額與實際一致。此筆會影響選定帳本的收支報表。</span></label>${errorBox}<button class="primary full">儲存對帳結果</button></form>`);const update=()=>{$('#expected-balance').textContent='該日帳面餘額：'+money(balanceAt(state(),$('#reconcile-account').value,$('#reconcile-date').value||today()))+'。信用卡／先買後付待繳款請輸入負數。'};$('#reconcile-account').onchange=update;$('#reconcile-date').onchange=update;update();submit('#reconcile-form',()=>finish(reconcile(state(),{account:$('#reconcile-account').value,date:$('#reconcile-date').value,actual:number('#reconcile-actual'),note:$('#reconcile-note').value,adjust:$('#reconcile-adjust').checked,bookId:bookId()}),'對帳結果已儲存'))}
function budgetsPage(){const key=bookId()+':'+c.getMonth(),limits=budgetStatus(state(),c.getMonth(),bookId()),period=cycleBounds(c.getMonth(),f().cycleDay);return title('預算，配合你的生活。','分類預算、月份起算日與帳本，照你的習慣安排。')+`<div class="settings-grid"><div class="card"><div class="card-heading"><h2>分類預算 · ${E(bookName(bookId()))}</h2></div><p class="help">${period.start} 至 ${addDays(period.end,-1)}；上方可切換月份與帳本。</p><form id="category-budget-form">${categoryList(state()).map(cat=>`<label class="budget-input-row"><span>${E(cat)}</span><input type="number" step="0.01" min="0" data-cat-budget="${E(cat)}" aria-label="${E(cat)}預算" placeholder="不設定" value="${f().categoryBudgets[key]?.[cat]===undefined?'':f().categoryBudgets[key][cat]/100}"></label>`).join('')}<button class="primary full" style="margin-top:20px">儲存分類預算</button></form>${limits.length?`<div style="margin-top:24px">${limits.map(x=>`<p class="help ${x.remaining<0?'overspent':''}">${E(x.category)} · 已用 ${money(x.used)}／預算 ${money(x.limit)} · ${x.remaining>=0?'剩餘':'超出'} ${money(Math.abs(x.remaining))}</p>`).join('')}</div>`:''}</div><div class="left-col"><div class="card"><div class="card-heading"><h2>我的帳本</h2></div>${f().books.map(b=>`<div class="due-row"><strong>${E(b.name)}</strong><button class="text-btn" data-rename-book="${E(b.id)}">改名</button></div>`).join('')}<form id="new-book-form" class="inline-form" style="margin-top:16px"><input id="new-book-name" aria-label="新帳本名稱" placeholder="新增帳本，例如：旅行" maxlength="40" required><button class="secondary">新增</button></form><p class="help">帳本分開統計收支，帳戶餘額共用。內部轉帳不會變成另一個帳本的收入；可在交易編輯頁更換帳本。</p></div><div class="card"><div class="card-heading"><h2>自訂分類</h2></div><div class="quick-pills">${f().categories.map(cat=>`<span class="pill">${E(cat)}</span>`).join('')||'<span class="help">尚未新增自訂分類。</span>'}</div><form id="new-category-form" class="inline-form"><input id="new-category-name" aria-label="新分類名稱" placeholder="例如：寵物、旅遊" maxlength="40" required><button class="secondary">新增</button></form></div><div class="card"><div class="card-heading"><h2>月份起算日</h2></div><form id="cycle-form">${input('每月幾日開始新月份？','cycle-day',f().cycleDay,'number','required min="1" max="31"')}<p class="help">例如薪資25日入帳，可設定每月25日至下月24日。日期不足時使用月底；此設定會一起更新總覽與分類預算。</p><button class="secondary">儲存起算日</button></form></div></div></div>`}
function backupPanel(){return `<div class="card advanced-backup" style="margin-top:24px"><div class="card-heading"><h2>${I('shield')} 自動備份與復原</h2><span class="pill">最近30個本機版本</span></div><p class="help">成功存檔後會建立本機歷史版本。它仍屬此瀏覽器資料；可另啟用雲端同步，或選擇外部資料夾／Google Drive 保存加密備份；歷史版本本身仍保存在此瀏覽器。</p><div class="notice" id="backup-status" role="status">${E(externalStatus||historyError||'本機歷史版本已啟用。外部自動備份尚未連接。')}</div><div class="row" style="flex-wrap:wrap;margin-top:16px"><button class="secondary" id="history-open">查看歷史版本</button><button class="secondary" id="trash-open">${I('trash')}刪除復原（${f().trash.length}）</button><button class="secondary" id="encrypted-download">下載加密備份</button><button class="secondary" id="encrypted-restore">還原加密備份</button></div><input type="file" id="encrypted-file" accept="application/json,.json" hidden><form id="backup-config-form" style="margin-top:24px">${input('備份密碼（至少8字元，僅本次使用）','backup-password','','password','minlength="8" autocomplete="new-password" placeholder="請自行保管，無法代為找回"')}${select('外部自動備份位置','backup-target',[['folder','自選資料夾／Drive 桌面同步資料夾'],['drive','Google Drive（需自行設定 OAuth）']],config.target)}<label class="check"><input type="checkbox" id="backup-auto" ${config.auto?'checked':''}><span>啟用外部自動加密備份：頁面開啟、密碼已解鎖且授權有效時，變更後自動備份，最快每分鐘一次。關閉網頁後不會繼續執行。</span></label><button class="primary">儲存備份設定／解鎖密碼</button></form><div class="row" style="flex-wrap:wrap;margin-top:16px"><button class="secondary" id="choose-backup-folder">選擇備份資料夾</button><button class="secondary" id="authorize-backup-folder">重新授權資料夾</button><button class="secondary" id="backup-now">立即外部備份</button></div><p class="help">${E(folderLabel?'資料夾：'+folderLabel:'資料夾尚未連接')} · 上次外部成功：${config.lastBackup?E(new Date(config.lastBackup).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'})):'尚無'}。密碼不寫入帳本、程式或備份；請另外保管。</p><details class="setup-details"><summary>Google Drive 連接設定與限制</summary><p class="help">此選項使用你自行建立的 Google OAuth Web 用戶端；目前沒有預先配置的共用登入 Client ID。請在 Google Cloud 啟用 Drive API、建立 Web OAuth 用戶端，並將本站來源加入允許的 JavaScript 來源：<code>${E(location.origin)}</code>。若應用仍在測試，請把使用帳號加入測試使用者。</p><form id="drive-prepare-form">${input('Google OAuth Web Client ID','drive-client-id',config.clientId,'text','placeholder="…apps.googleusercontent.com"')}<button class="secondary">儲存並載入 Google 登入元件</button></form><div class="row" style="margin-top:12px;flex-wrap:wrap"><button class="secondary" id="drive-connect" ${prepared?'':'disabled'}>連接自己的 Google Drive</button><button class="secondary" id="drive-disconnect">中斷連接</button><button class="secondary" id="drive-history" ${backups.driveStatus().connected?'':'disabled'}>雲端備份紀錄／還原</button></div><p class="help">僅請求 drive.file 權限，讀寫此工具建立的備份檔；上傳前以密碼加密，保留不同版本。Google 授權過期或重開網頁後需重新連接，未授權不會顯示備份成功。這是備份／還原，不會自動合併跨裝置帳目。</p><a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener noreferrer">開啟 Google OAuth 設定 ↗</a></details></div><div class="card" style="margin-top:24px"><div class="card-heading"><h2>提醒與通知</h2></div><p class="help">頁面內可檢查待繳，網頁開啟時可使用瀏覽器通知。要在關閉網頁後收到提醒，請匯入手機日曆，並在日曆確認提醒權限。</p><div class="row" style="flex-wrap:wrap"><button class="secondary" id="enable-foreground-notify">啟用網頁開啟時通知</button><button class="secondary" id="disable-foreground-notify">關閉網頁內通知</button><button class="secondary" id="calendar-export">匯出手機日曆提醒</button></div><p class="help">通知狀態：${config.notifications?'已啟用（仍依瀏覽器權限）':'未啟用'}。日曆匯出會包含目前帳本未來90天的待確認項目與前一天提醒；帳單變更後請重新更新日曆，避免保留舊日期。</p></div>`}
function updateBackupStatus(text){externalStatus=text;const el=$('#backup-status');if(el)el.textContent=text}
function externalBackup(manual=false){if(externalTask)return externalTask;externalTask=performExternalBackup(manual).finally(()=>externalTask=null);return externalTask}
async function beforeSwitch(){clearTimeout(backupTimer);if(externalTask)await externalTask.catch(()=>{});}
async function performExternalBackup(manual=false){if(c.isDemo()){toast('示範模式不會寫入外部備份');return}if(busy)return;if(!password){updateBackupStatus('外部備份等待解鎖密碼，帳目仍保存在本機。');if(manual)throw Error('請先設定／解鎖備份密碼');return}busy=true;try{const envelope=await backups.encryptBackup(state(),password);if(config.target==='drive'){const result=await backups.uploadDriveBackup(envelope);updateBackupStatus('Google Drive 已成功儲存加密備份：'+result.name)}else{const name=await backups.writeFolderBackup(envelope);updateBackupStatus('已成功寫入自選資料夾：'+name)}config.lastBackup=Date.now();lastExternal=Date.now();dirty=false;saveConfig()}catch(e){updateBackupStatus('外部備份尚未成功：'+e.message);if(manual)throw e}finally{busy=false}}
function onChange(next,label='自動快照'){if(c.isDemo())return;const targetScope=backups.getBackupScope();historyQueue=historyQueue.then(()=>backups.saveVersion(next,label,targetScope)).catch(e=>{historyError='本機版本備份未完成：'+e.message;updateBackupStatus(historyError)});dirty=true;if(config.auto){clearTimeout(backupTimer);backupTimer=setTimeout(()=>externalBackup(false),Math.max(1500,60000-(Date.now()-lastExternal)))}}
async function restoreState(raw,label){if(c.isDemo()){toast('請先回到我的帳本，再還原真實備份');return}const checked=upgrade(validateBackup(raw));if(!confirm(`將以「${label}」的 ${checked.transactions.length} 筆交易取代目前帳本。先保留目前本機快照，再還原，確定嗎？`))return;const targetScope=backups.getBackupScope();await backups.saveVersion(state(),'還原前保護版本',targetScope);if(backups.getBackupScope()!==targetScope)throw Error('帳號已切換，請重新還原');finish(checked,'已還原備份');}
function passwordForm(title,action){sheet(title,`<form id="backup-password-form">${input('備份密碼','restore-password','','password','required minlength="8" autocomplete="off"')}${errorBox}<button class="primary full">繼續</button></form>`);submit('#backup-password-form',async()=>{const p=$('#restore-password').value;await action(p)})}
async function historySheet(){try{historyRows=await backups.history();sheet('本機歷史版本',`<p class="help">最多保留最近30個版本；與帳目同屬此瀏覽器，不能取代外部備份。</p>${historyRows.map(r=>`<div class="due-row"><div><strong>${E(r.label)}</strong><small>${new Date(r.time).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'})} · ${r.count}筆</small></div><button class="secondary" data-restore-history="${E(r.id)}">還原</button></div>`).join('')||empty('尚無歷史版本，成功記帳後會自動建立。')}`);$$('[data-restore-history]').forEach(b=>b.onclick=async()=>{try{const r=historyRows.find(x=>x.id===b.dataset.restoreHistory);await restoreState(JSON.parse(r.text),'本機歷史版本')}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
function trashSheet(){sheet('刪除紀錄復原',`<p class="help">保留最近100筆刪除紀錄，還原前會檢查編號與固定收支是否重複。</p>${f().trash.map(r=>`<div class="due-row"><div><strong>${E(r.tx.note)}</strong><small>${r.tx.date} · ${money(r.tx.amount)} · ${E(bookName(r.tx.bookId||'personal'))}</small></div><button class="secondary" data-restore-trash="${E(r.id)}">復原</button></div>`).join('')||empty('回收桶目前是空的。')}`);$$('[data-restore-trash]').forEach(b=>b.onclick=()=>{try{finish(restoreTransaction(state(),b.dataset.restoreTrash),'紀錄已復原')}catch(e){toast(e.message)}})}
async function driveHistory(){cloudRows=await backups.listDriveBackups();sheet('Google Drive 加密備份',`${cloudRows.map(r=>`<div class="due-row"><div><strong>${E(r.name)}</strong><small>${E(r.createdTime||'')}</small></div><button class="secondary" data-cloud-restore="${E(r.id)}">解密還原</button></div>`).join('')||empty('尚無此工具建立的雲端備份。')}`);$$('[data-cloud-restore]').forEach(b=>b.onclick=()=>{const id=b.dataset.cloudRestore;passwordForm('解密雲端備份',async p=>{const envelope=await backups.readDriveBackup(id);await restoreState(await backups.decryptBackup(envelope,p),'Google Drive 備份')})})}
function exportCalendar(){const events=upcoming(state(),{from:today(),to:addDays(today(),90),bookId:scope()});if(!events.length){toast('未來90天沒有待確認排程');return}download(calendarICS(events),'日常有餘_帳單提醒_'+today()+'.ics','text/calendar;charset=utf-8');toast('已匯出，請在手機日曆匯入並確認通知設定')}
async function notifyDue(force=false){if(c.isDemo()||!config.notifications||!('Notification'in window)||Notification.permission!=='granted')return;const pending=upcoming(state(),{from:addDays(today(),-7),to:addDays(today(),3),includeIncome:false});if(!pending.length)return;const tag='yoyu-'+today();if(!force&&localStorage.getItem('yoyu-notify-tag')===tag)return;const reg=await Promise.race([navigator.serviceWorker?.ready,new Promise(resolve=>setTimeout(()=>resolve(null),3000))]);if(reg?.showNotification){await reg.showNotification('日常有餘 · 待繳提醒',{body:'近期有 '+pending.length+' 筆帳款尚未確認，請開啟帳本查看。',tag,icon:'./icon-192.png',data:{url:location.origin+'/'}});localStorage.setItem('yoyu-notify-tag',tag)}else if(typeof Notification==='function'){new Notification('日常有餘 · 待繳提醒',{body:'近期有 '+pending.length+' 筆帳款尚未確認，請開啟帳本查看。',tag});localStorage.setItem('yoyu-notify-tag',tag)}}
function bind(){
 $('#active-book')?.addEventListener('change',e=>c.setBook(e.target.value));$('#advanced-month')?.addEventListener('change',e=>{if(e.target.value)c.setMonth(e.target.value)});$$('[data-advanced-page]').forEach(b=>b.onclick=()=>c.navigate(b.dataset.advancedPage));$$('[data-confirm-due]').forEach(b=>b.onclick=()=>confirmDue(b.dataset.confirmDue));$('#new-plan')?.addEventListener('click',()=>planForm());$$('[data-edit-plan]').forEach(b=>b.onclick=()=>planForm(b.dataset.editPlan));$$('[data-plan-detail]').forEach(b=>b.onclick=()=>planDetail(b.dataset.planDetail));$$('[data-plan-payoff]').forEach(b=>b.onclick=()=>paymentForm(b.dataset.planPayoff));$$('[data-plan-refund]').forEach(b=>b.onclick=()=>refundForm(b.dataset.planRefund));$('#new-bill')?.addEventListener('click',()=>billForm());$$('[data-edit-bill]').forEach(b=>b.onclick=()=>billForm(b.dataset.editBill));$$('[data-toggle-bill]').forEach(b=>b.onclick=()=>{const s=upgrade(state()),v=s.features.bills.find(x=>x.id===b.dataset.toggleBill);v.active=!v.active;set(s,v.active?'已恢復未來排程':'已暫停未來排程，歷史紀錄保留')});$('#new-reconcile')?.addEventListener('click',reconcileForm);$$('[data-inspect-tx]').forEach(b=>b.onclick=()=>c.editTransaction(b.dataset.inspectTx));$$('#calendar-export').forEach(b=>b.onclick=exportCalendar);
 $('#category-budget-form')?.addEventListener('submit',e=>{e.preventDefault();try{const s=upgrade(state()),limits={};$$('[data-cat-budget]').forEach(el=>{if(el.value!=='')limits[el.dataset.catBudget]=cents(el.value)});s.features.categoryBudgets[bookId()+':'+c.getMonth()]=limits;set(s,'分類預算已儲存')}catch(e){toast(e.message)}});
 $('#new-book-form')?.addEventListener('submit',e=>{e.preventDefault();const name=$('#new-book-name').value.trim();if(!name)return;const s=upgrade(state());if(s.features.books.some(b=>b.name===name)){toast('已有相同名稱的帳本');return}s.features.books.push({id:uid(),name});set(s,'帳本已新增')});$$('[data-rename-book]').forEach(b=>b.onclick=()=>{const current=f().books.find(x=>x.id===b.dataset.renameBook),name=prompt('帳本新名稱',current.name)?.trim();if(!name)return;if(name.length>40){toast('名稱最多40字');return}const s=upgrade(state());s.features.books.find(x=>x.id===current.id).name=name;set(s,'帳本名稱已更新')});
 $('#new-category-form')?.addEventListener('submit',e=>{e.preventDefault();const name=$('#new-category-name').value.trim();if(!name)return;if(categoryList(state()).includes(name)){toast('分類已存在');return}const s=upgrade(state());s.features.categories.push(name);set(s,'自訂分類已新增')});$('#cycle-form')?.addEventListener('submit',e=>{e.preventDefault();const s=upgrade(state());s.features.cycleDay=Number($('#cycle-day').value);set(s,'月份起算日已更新')});
 $('#history-open')?.addEventListener('click',historySheet);$('#trash-open')?.addEventListener('click',trashSheet);
 $('#encrypted-download')?.addEventListener('click',()=>passwordForm('下載加密備份',async p=>{const envelope=await backups.encryptBackup(state(),p);download(JSON.stringify(envelope),'日常有餘_加密備份_'+today()+'.yoyu.json','application/json');$('#sheet').close();toast('加密備份已下載，請自行保管密碼')}));$('#encrypted-restore')?.addEventListener('click',()=>$('#encrypted-file').click());$('#encrypted-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>25*1024*1024)throw Error('備份大於25MB');const envelope=JSON.parse(await file.text());passwordForm('還原加密備份',async p=>restoreState(await backups.decryptBackup(envelope,p),'加密備份'))}catch(e){toast(e.message)}finally{e.target.value=''}});
 $('#backup-config-form')?.addEventListener('submit',e=>{e.preventDefault();const value=$('#backup-password').value;if(value&&value.length<8){toast('密碼至少8字元');return}if(value)password=value;config.auto=$('#backup-auto').checked;config.target=$('#backup-target').value;if(config.auto&&!password){toast('請先填寫本次備份密碼');return}saveConfig();c.render();toast('備份設定已儲存；密碼僅本次使用');if(config.auto&&dirty)externalBackup(false)});
 $('#choose-backup-folder')?.addEventListener('click',async()=>{try{folderLabel=await backups.chooseFolder();updateBackupStatus('資料夾已連接：'+folderLabel);c.render()}catch(e){if(e.name!=='AbortError')toast(e.message)}});$('#authorize-backup-folder')?.addEventListener('click',async()=>{try{folderLabel=await backups.authorizeFolder();updateBackupStatus('資料夾寫入已授權');c.render()}catch(e){toast(e.message)}});$('#backup-now')?.addEventListener('click',async()=>{try{const typed=$('#backup-password')?.value;if(typed)password=typed;config.target=$('#backup-target')?.value||config.target;await externalBackup(true);c.render()}catch(e){toast(e.message)}});
 $('#drive-prepare-form')?.addEventListener('submit',async e=>{e.preventDefault();try{config.clientId=$('#drive-client-id').value.trim();await backups.prepareDrive(config.clientId);prepared=true;saveConfig();c.render();toast('登入元件已載入，請按「連接自己的 Google Drive」')}catch(e){toast(e.message)}});$('#drive-connect')?.addEventListener('click',()=>{try{backups.connectDrive().then(()=>{updateBackupStatus('Google Drive 已授權，尚未上傳備份。');c.render()}).catch(e=>toast(e.message))}catch(e){toast(e.message)}});$('#drive-disconnect')?.addEventListener('click',()=>{backups.disconnectDrive();updateBackupStatus('Google Drive 已中斷，此次授權令牌已清除。');c.render()});$('#drive-history')?.addEventListener('click',()=>driveHistory().catch(e=>toast(e.message)));
 $('#enable-foreground-notify')?.addEventListener('click',async()=>{try{if(!('Notification'in window))throw Error('此瀏覽器不支援通知，請改用手機日曆提醒');const result=await Notification.requestPermission();if(result!=='granted')throw Error('尚未允許通知；請改用日曆或到瀏覽器設定開啟');config.notifications=true;saveConfig();await notifyDue(true);c.render();toast('已啟用網頁開啟時通知；關閉後請使用日曆提醒')}catch(e){toast(e.message)}});$('#disable-foreground-notify')?.addEventListener('click',()=>{config.notifications=false;saveConfig();c.render();toast('已關閉網頁內通知')});
}
function repayAccount(accountId){const plans=f().plans.filter(p=>p.account===accountId&&planRemaining(p)>0);if(!plans.length)return false;sheet('選擇要還款的分期方案',`<p class="help">此帳戶有已管理的分期，請選擇方案，以同步待繳與每期進度。這裡只記錄帳目，不會操作實際付款。</p>${plans.map(p=>`<div class="due-row"><div><strong>${E(p.name)}</strong><small>待還本金 ${money(planRemaining(p))}</small></div><button class="secondary" data-repay-managed="${E(p.id)}">記錄還款</button></div>`).join('')}`);$$('[data-repay-managed]').forEach(b=>b.onclick=()=>paymentForm(b.dataset.repayManaged));return true}
function entryFields(t){return `<div class="row">${select('所屬帳本','entry-book',books(),t.bookId||bookId())}${input('標籤（以逗號分開）','entry-tags',(t.tags||[]).join('，'),'text','maxlength="300" placeholder="例如：代墊、出差"')}</div>`}
function captureEntryMeta(t){t.bookId=$('#entry-book')?.value||t.bookId||bookId();t.tags=($('#entry-tags')?.value||'').split(/[，,]/).map(s=>s.trim()).filter(Boolean).slice(0,20)}
async function init(){if(c.isDemo())return;try{await backups.saveVersion(state(),'開啟帳本保護版本');const info=await backups.folderInfo();folderLabel=info?.name||''}catch(e){historyError='歷史備份未就緒：'+e.message}try{if(navigator.storage?.persist)await navigator.storage.persist()}catch{}setInterval(()=>notifyDue().catch(()=>{}),60000)}
return {beforeSwitch,switchScope,toolbar,homePanel,backupPanel,bind,onChange,entryFields,captureEntryMeta,init,repayAccount,pages:{plans:plansPage,bills:billsPage,cashflow:cashflowPage,reconcile:reconcilePage,budgets:budgetsPage},openPlan:planForm};
}
